class $$BranchesTableTableManager
    extends
        RootTableManager<
          _$DokanDatabase,
          $BranchesTable,
          Branch,
          $$BranchesTableFilterComposer,
          $$BranchesTableOrderingComposer,
          $$BranchesTableAnnotationComposer,
          $$BranchesTableCreateCompanionBuilder,
          $$BranchesTableUpdateCompanionBuilder,
          (Branch, $$BranchesTableReferences),
          Branch,
          PrefetchHooks Function({
            bool invoiceCountersRefs,
            bool usersRefs,
            bool shiftsRefs,
            bool paymentsRefs,
            bool productBranchOverridesRefs,
            bool purchasesRefs,
            bool salesRefs,
            bool refundsRefs,
            bool stockAdjustmentsRefs,
            bool stockBalancesRefs,
            bool stockMovementsRefs,
            bool userBranchesRefs,
          })
        > {
  $$BranchesTableTableManager(_$DokanDatabase db, $BranchesTable table)
    : super(
        TableManagerState(
          db: db,
          table: table,
          createFilteringComposer: () =>
              $$BranchesTableFilterComposer($db: db, $table: table),
          createOrderingComposer: () =>
              $$BranchesTableOrderingComposer($db: db, $table: table),
          createComputedFieldComposer: () =>
              $$BranchesTableAnnotationComposer($db: db, $table: table),
          updateCompanionCallback:
              ({
                Value<SyncStatus> syncStatus = const Value.absent(),
                Value<DateTime> updatedAt = const Value.absent(),
                Value<int> version = const Value.absent(),
                Value<bool> isDeleted = const Value.absent(),
                Value<String> id = const Value.absent(),
                Value<String> code = const Value.absent(),
                Value<String> name = const Value.absent(),
                Value<String?> nameAr = const Value.absent(),
                Value<String?> address = const Value.absent(),
                Value<String?> phone = const Value.absent(),
                Value<bool> isDefault = const Value.absent(),
                Value<bool> isActive = const Value.absent(),
                Value<int> rowid = const Value.absent(),
              }) => BranchesCompanion(
                syncStatus: syncStatus,
                updatedAt: updatedAt,
                version: version,
                isDeleted: isDeleted,
                id: id,
                code: code,
                name: name,
                nameAr: nameAr,
                address: address,
                phone: phone,
                isDefault: isDefault,
                isActive: isActive,
                rowid: rowid,
              ),
          createCompanionCallback:
              ({
                Value<SyncStatus> syncStatus = const Value.absent(),
                Value<DateTime> updatedAt = const Value.absent(),
                Value<int> version = const Value.absent(),
                Value<bool> isDeleted = const Value.absent(),
                Value<String> id = const Value.absent(),
                required String code,
                required String name,
                Value<String?> nameAr = const Value.absent(),
                Value<String?> address = const Value.absent(),
                Value<String?> phone = const Value.absent(),
                Value<bool> isDefault = const Value.absent(),
                Value<bool> isActive = const Value.absent(),
                Value<int> rowid = const Value.absent(),
              }) => BranchesCompanion.insert(
                syncStatus: syncStatus,
                updatedAt: updatedAt,
                version: version,
                isDeleted: isDeleted,
                id: id,
                code: code,
                name: name,
                nameAr: nameAr,
                address: address,
                phone: phone,
                isDefault: isDefault,
                isActive: isActive,
                rowid: rowid,
              ),
          withReferenceMapper: (p0) => p0
              .map(
                (e) => (
                  e.readTable<$BranchesTable, Branch>(table),
                  $$BranchesTableReferences(db, table, e),
                ),
              )
              .toList(),
          prefetchHooksCallback:
              ({
                invoiceCountersRefs = false,
                usersRefs = false,
                shiftsRefs = false,
                paymentsRefs = false,
                productBranchOverridesRefs = false,
                purchasesRefs = false,
                salesRefs = false,
                refundsRefs = false,
                stockAdjustmentsRefs = false,
                stockBalancesRefs = false,
                stockMovementsRefs = false,
                userBranchesRefs = false,
              }) {
                return PrefetchHooks(
                  db: db,
                  explicitlyWatchedTables: [
                    if (invoiceCountersRefs) db.invoiceCounters,
                    if (usersRefs) db.users,
                    if (shiftsRefs) db.shifts,
                    if (paymentsRefs) db.payments,
                    if (productBranchOverridesRefs) db.productBranchOverrides,
                    if (purchasesRefs) db.purchases,
                    if (salesRefs) db.sales,
